def geometric_sum(n):
    # Base case: if n is 0, the geometric sum is 1
    if n == 0:
        return 1
    # Recursive case: calculate the geometric sum for n-1 and add 1/(2^n)
    else:
        return 1 / (2 ** n) + geometric_sum(n - 1)
